type Person struct{ courses []Course }          // unexported: package-private

func (p *Person) Courses() []Course { return slices.Clone(p.courses) }

func (p *Person) AddCourse(c Course) error {
    if !c.accepted() { return ErrNotAccepted }
    p.courses = append(p.courses, c)
    return nil
}

func (p *Person) Courses() iter.Seq[Course] {
    return func(yield func(Course) bool) {
        for _, c := range p.courses {
            if !yield(c) { return }
        }
    }
}

